userscript.function:

// 현재 팝업에서 사용될 조건들의 판단 및 설정을 전역변수에 담는다.
// 검색조건 설정
if(sUtils.workflow.check('US1637133464814')){
	// 용도기준검색
	searchOption = "USE";
}
// 다중선택 설정
if(sUtils.workflow.check('US1637133475235') && Sepoa.request.EXTERNAL_FLAG != 'Y'){
	// 다중선택
	selectOption = "MULTI";
}
//멀티 싱글 커스텀
if(Sepoa.request.SELECT_OPTION) {
	selectOption = Sepoa.request.SELECT_OPTION;
}


var sealType = Sepoa.request.SEAL_TYPE;
var sealUseType = Sepoa.request.SEAL_USE_TYPE;
var keyword = filterObj.getValue('F_KEYWORD');
var ext_flag = Sepoa.request.EXTERNAL_FLAG;
var flagArr = Sepoa.request.FLAGARR;
var apply_type = Sepoa.request.APPLY_TYPE;

gridObj.setColumnHidden(gridObj.getColIndexById('SEAL_COMP_FLAG'), true);
gridObj.setColumnHidden(gridObj.getColIndexById('EXT_OUT_EXPECT_DATE'), true);

if (!sUtils.workflow.check('US1682656641829')) { //카테고리, 공통인감 여부 셋팅
    gridObj.setColumnHidden(gridObj.getColIndexById('SEAL_CATEGORY'), 1); //카테고리 숨김
}

if(ext_flag != 'Y'){
	gridObj.setColumnHidden(gridObj.getColIndexById('COMPLETE_FLAG'), true);
	gridObj.setColumnHidden(gridObj.getColIndexById('EXT_OUT_EXPECT_DATE'), true);
	gridObj.setColumnHidden(gridObj.getColIndexById('EXT_IN_EXPECT_DATE'), true);
	if(flagArr == 'R' && sUtils.workflow.check('SID1662525446456')){
		gridObj.setColumnHidden(gridObj.getColIndexById('SEAL_COMP_FLAG'), false);
		gridObj.setColumnHidden(gridObj.getColIndexById('EXT_IN_EXPECT_DATE'), false);
	}
}

dataOutput.addFilter(filterObj);
dataOutput.setValue('SEAL_STATUS', 'C');
dataOutput.setValue('SEAL_TYPE', sealType);
dataOutput.setValue('SEAL_USE_TYPE', sealUseType);
dataOutput.setValue('CHECK_SEAL_USE_TYPE', 'N');
dataOutput.setValue('EXTERNAL_FLAG', ext_flag);
dataOutput.setValue('FLAGARR', flagArr);
dataOutput.setValue('APPLY_TYPE', apply_type);
// 인장선택 팝업만: 전자/실물/반출 중 하나라도 Y인 인장만 조회
dataOutput.setValue('REQUIRE_USAGE_FLAG', 'Y');

if(searchOption == 'DEPT') {
	dataOutput.setValue('DEPT_NAME', keyword);
}

gridObj.postConnection(window.CONTEXT_NAME+'/SepoaGrid.sux',['mode=doQuery','METHOD=doSelectSealService','PROCESS_ID=sepoa.svc.seal.SepoaReqSealService']);
gridObj.clearAll(false);


        	var selectedRow = gridObj.getGridChangedRows("SELECTED");
        	var applyType = Sepoa.request.APPLY_TYPE;
        	var beforeSelectedSeal = Sepoa.request.SELECTED_SEAL_ID;
        	gridObj.editStop();

        	if (selectedRow.length < 1) {
                Alert(Sepoa.cache.text.get('MESSAGE.1004')); //선택된 데이터가 없습니다.
                return;
            }

            if(selectOption == 'SINGLE'){
            	if (selectedRow.length > 1) {
	                Alert(Sepoa.cache.text.get('SLM_221_P.MSG_0001'));	// 하나의 인감만 선택해주세요.
	                return;
	            }
            }

            for(var i in selectedRow) {
	           	var comp_flag = gridObj.cells(selectedRow[i], gridObj.getColIndexById("COMPLETE_FLAG")).getValue();
	           	if((dataOutput.getValue('EXTERNAL_FLAG') == 'Y' && comp_flag == 'N')   //반출 신청일 경우 
	           	   || (sUtils.workflow.check('SID1662525446456') && dataOutput.getValue('EXTERNAL_FLAG') == '' && dataOutput.getValue('FLAGARR') == 'R' && comp_flag == 'N')){ //날인 신청일 경우
	                Alert(Sepoa.cache.text.get('SLM_221_P.MSG_0006'));	// 반출된 인감입니다.
	                return;
	            }
            }

            for(var i in selectedRow) {
            	var sealStatus = gridObj.cells(selectedRow[i], gridObj.getColIndexById("SEAL_STATUS")).getValue();
            	if(sealStatus != 'C') {
            		Alert(Sepoa.cache.text.get('SLM_221_P.MSG_0005')); // 사용할 수 없는 인감 상태입니다.
            		return;
            	}
            }

        	if(typeof(applyType) != 'undefined' && applyType == 'U' && typeof(beforeSelectedSeal) != 'undefined' && selectOption == 'SINGLE') {
        		for(var i in selectedRow) {
        			var selectSeal = gridObj.cells(selectedRow[i], gridObj.getColIndexById("MANAGE_NUMBER")).getValue();
        			if(beforeSelectedSeal != selectSeal) {
        				Alert(Sepoa.cache.text.get('SLM_221_P.MSG_0002'));
        				return;
        			}
        		}
        	}

        	var paramArray = gridObj._getSelectedData("SELECTED");

            Confirm(Sepoa.cache.text.get('SLM_221_P.MSG_0003'), function(flag) {
            	if(flag){
            		if (Sepoa.params && Sepoa.params.callback) {
                        Sepoa.params.callback(paramArray);
                    }
                    selfObj.close();
            	}
            });


            var header = this.getColumnId();
            var selected = gridObj.cells(id, gridObj.getColIndexById("SELECTED")).getValue();
            if(selected == 0){
				gridObj.cells(id, gridObj.getColIndexById("SELECTED")).setValue(1);            
            } else {
            	gridObj.cells(id, gridObj.getColIndexById("SELECTED")).setValue(0);
            }


	if (count == 0) {
        Alert(Sepoa.cache.text.get('MESSAGE.1001'));
        return;
    } 

    for (var i = 0; i < count; i++) {
       if (gridObj.cells2(i, gridObj.getColIndexById('COMPLETE_FLAG')).getValue() == 'Y') {
           gridObj.cells2(i, gridObj.getColIndexById('EXT_OUT_EXPECT_DATE')).setValue('');
           gridObj.cells2(i, gridObj.getColIndexById('EXT_OUT_EXPECT_TIME')).setValue('');
           gridObj.cells2(i, gridObj.getColIndexById('EXT_IN_EXPECT_DATE')).setValue('');
           gridObj.cells2(i, gridObj.getColIndexById('EXT_IN_EXPECT_TIME')).setValue('');
           gridObj.cells2(i, gridObj.getColIndexById('SEAL_COMP_FLAG')).setValue('Y');
       }else{
           gridObj.cells2(i, gridObj.getColIndexById('SEAL_COMP_FLAG')).setValue('N');
       }
   }
